"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { type ViewerResource } from "@/lib/viewer-resource"
import {
  ViewerBody,
  ViewerHeader,
  ViewerRoot,
  ViewerSidebar,
  ViewerSidebarTrigger,
  ViewerSurface,
  type ViewerRootProps,
  type ViewerSidebarProps,
  type ViewerSidebarTriggerProps,
  type ViewerSurfaceProps,
} from "@/components/ui/viewer"

import {
  type FileCategory,
  type FileDescriptor,
  type FileViewerProps as FileViewerCoreProps,
} from "./file-viewer-core"
import {
  FileViewerDocument,
  InternalFileViewerDocument,
} from "./file-viewer-document"
import {
  FileViewerProvider,
  useFileViewerContext,
} from "./file-viewer-internal"
import { ViewerControls, type ViewerControlsState } from "./viewer-controls"

export { type FileCategory } from "./file-viewer-core"
export {
  FileViewerDocument,
  type FileViewerDocumentProps,
} from "./file-viewer-document"
export { useFileViewerResource } from "./file-viewer-internal"

export type FileViewerProps = FileViewerCoreProps &
  Pick<
    ViewerRootProps,
    | "defaultOpen"
    | "inlineBreakpoint"
    | "mode"
    | "onOpenChange"
    | "open"
    | "sidebarCollapsible"
    | "sidebarSide"
  > & {
    children?: React.ReactNode
  }

export type FileViewerHeaderProps = React.ComponentProps<typeof ViewerHeader>

export type FileViewerTitleProps = React.ComponentProps<"div">

export type FileViewerMetaProps = React.ComponentProps<"span">

export type FileViewerControlsProps = Omit<
  React.ComponentProps<typeof ViewerControls>,
  "downloads" | "position" | "rotate" | "subtitle" | "title" | "zoom"
>

export type FileViewerBodyProps = React.ComponentProps<typeof ViewerBody>
export type FileViewerSidebarProps = ViewerSidebarProps
export type FileViewerSurfaceProps = ViewerSurfaceProps
export type FileViewerSidebarTriggerProps = ViewerSidebarTriggerProps

type FileViewerState = {
  descriptor: FileDescriptor
  resource: ViewerResource
  controlsState: ViewerControlsState | null
  setControlsState: (state: ViewerControlsState | null) => void
}

type FileViewerHeaderState = FileViewerState

function useFileViewer(): FileViewerState {
  const { descriptor, resource, setControlsState, controlsState } =
    useFileViewerContext()
  return React.useMemo(
    () => ({
      descriptor,
      resource,
      setControlsState,
      controlsState,
    }),
    [descriptor, resource, setControlsState, controlsState]
  )
}

function useFileViewerHeader(): FileViewerHeaderState {
  return useFileViewer()
}

export function FileViewerHeader({
  children,
  className,
  ...props
}: FileViewerHeaderProps) {
  return (
    <ViewerHeader
      data-slot="file-viewer-header"
      className={cn(
        "flex min-h-10 flex-wrap items-center gap-2 px-2 py-1 sm:flex-nowrap sm:py-0",
        className
      )}
      {...props}
    >
      {children ?? (
        <>
          <FileViewerTitle />
          <FileViewerMeta />
          <FileViewerControls />
        </>
      )}
    </ViewerHeader>
  )
}

export function FileViewerTitle({ className, ...props }: FileViewerTitleProps) {
  const { descriptor } = useFileViewerHeader()

  return (
    <div
      data-slot="file-viewer-title"
      className={cn("flex min-w-0 shrink items-center gap-2", className)}
      {...props}
    >
      <span
        className="min-w-0 truncate text-sm font-medium"
        title={descriptor.displayName}
      >
        {descriptor.displayName}
      </span>
    </div>
  )
}

export function FileViewerMeta({ className, ...props }: FileViewerMetaProps) {
  const { descriptor, resource } = useFileViewerHeader()
  const meta = resource.mimeType || descriptor.mimeType || descriptor.category

  if (!meta) return null

  return (
    <span
      data-slot="file-viewer-meta"
      className={cn(
        "shrink-0 truncate text-xs text-muted-foreground",
        className
      )}
      {...props}
    >
      {meta}
    </span>
  )
}

export function FileViewerControls({
  className,
  extra,
  ...props
}: FileViewerControlsProps) {
  const { resource, controlsState } = useFileViewerHeader()
  const registeredDownloads = controlsState?.downloads
  const downloads =
    registeredDownloads !== undefined
      ? registeredDownloads
      : [resource.originalDownload]

  return (
    <ViewerControls
      data-slot="file-viewer-controls"
      className={cn(
        "ml-0 h-auto min-w-0 basis-full border-b-0 bg-transparent px-0 sm:ml-auto sm:basis-auto",
        className
      )}
      downloads={downloads}
      extra={extra ?? controlsState?.extra}
      loading={controlsState?.loading ?? false}
      position={controlsState?.position ?? null}
      rotate={controlsState?.rotate ?? null}
      zoom={controlsState?.zoom ?? null}
      {...props}
    />
  )
}

export function FileViewerBody({ className, ...props }: FileViewerBodyProps) {
  return (
    <ViewerBody data-slot="file-viewer-body" className={className} {...props} />
  )
}

export function FileViewerSidebar(props: FileViewerSidebarProps) {
  return <ViewerSidebar data-slot="file-viewer-sidebar" {...props} />
}

export function FileViewerSurface({
  className,
  ...props
}: FileViewerSurfaceProps) {
  return (
    <ViewerSurface
      data-slot="file-viewer-surface"
      className={className}
      {...props}
    />
  )
}

export function FileViewerSidebarTrigger({
  className,
  ...props
}: FileViewerSidebarTriggerProps) {
  return (
    <ViewerSidebarTrigger
      data-slot="file-viewer-sidebar-trigger"
      className={className}
      {...props}
    />
  )
}

export function FileViewer({
  as,
  bare = false,
  children,
  className,
  defaultOpen,
  inlineBreakpoint,
  isolateStyles,
  mode,
  onOpenChange,
  open,
  sidebarCollapsible,
  sidebarSide,
  source,
}: FileViewerProps) {
  if (children != null) {
    return (
      <FileViewerProvider as={as} isolateStyles={isolateStyles} source={source}>
        <ViewerRoot
          bare={bare}
          className={cn("h-full", className)}
          defaultOpen={defaultOpen}
          inlineBreakpoint={inlineBreakpoint}
          mode={mode}
          onOpenChange={onOpenChange}
          open={open}
          sidebarCollapsible={sidebarCollapsible}
          sidebarSide={sidebarSide}
        >
          {children}
        </ViewerRoot>
      </FileViewerProvider>
    )
  }

  if (bare) {
    return (
      <FileViewerProvider as={as} isolateStyles={isolateStyles} source={source}>
        <FileViewerDocument bare className={className} />
      </FileViewerProvider>
    )
  }

  return (
    <FileViewerProvider as={as} isolateStyles={isolateStyles} source={source}>
      <ViewerRoot
        className={cn("h-full", className)}
        defaultOpen={defaultOpen}
        inlineBreakpoint={inlineBreakpoint}
        mode={mode}
        onOpenChange={onOpenChange}
        open={open}
        sidebarCollapsible={sidebarCollapsible}
        sidebarSide={sidebarSide}
      >
        {children ?? (
          <>
            <FileViewerHeader />
            <FileViewerBody>
              <FileViewerSurface>
                <InternalFileViewerDocument
                  bare
                  className="h-full"
                  leafControls={false}
                  leafDownload={false}
                />
              </FileViewerSurface>
            </FileViewerBody>
          </>
        )}
      </ViewerRoot>
    </FileViewerProvider>
  )
}

"use client"

import * as React from "react"

import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"
import { useIsClient } from "@/components/ui/use-is-client"

import {
  descriptorResetKey,
  resolveFileDescriptor,
  type FileDescriptor,
  type FileViewerProps as FileViewerCoreProps,
} from "./file-viewer-core"
import {
  ViewerControlsRegistrationProvider,
  type ViewerControlsState,
} from "./viewer-controls"

type FileViewerProviderProps = Pick<
  FileViewerCoreProps,
  "as" | "isolateStyles" | "source"
> & {
  children: React.ReactNode
}

type FileViewerContextValue = {
  descriptor: FileDescriptor
  descriptorKey: string
  descriptorSignal: AbortSignal
  isClient: boolean
  isolateStyles: boolean
  resource: ViewerResource
  controlsState: ViewerControlsState | null
  setControlsState: (state: ViewerControlsState | null) => void
}

const FileViewerContext = React.createContext<FileViewerContextValue | null>(
  null
)

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

function useDescriptorSignal(descriptorKey: string): AbortSignal {
  const controller = React.useMemo(() => {
    void descriptorKey
    return new AbortController()
  }, [descriptorKey])
  const abortTimerRef = React.useRef<{
    controller: AbortController
    timer: ReturnType<typeof setTimeout>
  } | null>(null)

  useIsomorphicLayoutEffect(() => {
    if (abortTimerRef.current?.controller === controller) {
      clearTimeout(abortTimerRef.current.timer)
      abortTimerRef.current = null
    }

    return () => {
      const abortTimer = {
        controller,
        timer: setTimeout(() => {
          controller.abort()
          if (abortTimerRef.current === abortTimer) {
            abortTimerRef.current = null
          }
        }, 0),
      }
      abortTimerRef.current = abortTimer
    }
  }, [controller])

  return controller.signal
}

export function useFileViewerContext() {
  const context = React.useContext(FileViewerContext)
  if (!context) {
    throw new Error("File viewer parts must be used within FileViewer.")
  }
  return context
}

export function useOptionalFileViewerResource(): ViewerResource | null {
  return React.useContext(FileViewerContext)?.resource ?? null
}

export function useFileViewerResource(): ViewerResource {
  const resource = useOptionalFileViewerResource()
  if (!resource) {
    throw new Error("useFileViewerResource must be used within FileViewer.")
  }
  return resource
}

export function FileViewerProvider({
  as,
  children,
  isolateStyles = false,
  source,
}: FileViewerProviderProps) {
  const isClient = useIsClient()
  const [controlsState, setControlsState] =
    React.useState<ViewerControlsState | null>(null)
  const handleControlsChange = React.useCallback(
    (state: ViewerControlsState | null) => {
      setControlsState(state)
    },
    []
  )
  const resource = React.useMemo(
    () => createViewerResource(source, as),
    [source, as]
  )
  const descriptor = resolveFileDescriptor({ source, as })
  const descriptorKey = descriptorResetKey(descriptor)
  const descriptorSignal = useDescriptorSignal(descriptorKey)
  const value = React.useMemo<FileViewerContextValue>(
    () => ({
      descriptor,
      descriptorKey,
      descriptorSignal,
      isClient,
      isolateStyles,
      resource,
      setControlsState: handleControlsChange,
      controlsState,
    }),
    [
      descriptor,
      descriptorKey,
      descriptorSignal,
      handleControlsChange,
      isClient,
      isolateStyles,
      resource,
      controlsState,
    ]
  )

  return (
    <FileViewerContext.Provider value={value}>
      <ViewerControlsRegistrationProvider
        onControlsChange={handleControlsChange}
      >
        {children}
      </ViewerControlsRegistrationProvider>
    </FileViewerContext.Provider>
  )
}

"use client"

import * as React from "react"

import { type ViewerResource } from "@/lib/viewer-resource"

import {
  type FileDescriptor,
  type FileViewerProps as FileViewerCoreProps,
} from "./file-viewer-core"
import { FileErrorBoundary, ViewerFallback } from "./file-viewer-fallback"
import { useFileViewerContext } from "./file-viewer-internal"
import { FileViewerRoute } from "./file-viewer-route"
import { type ViewerControlsState } from "./viewer-controls"

export type FileViewerDocumentProps = Pick<
  FileViewerCoreProps,
  "bare" | "className"
>

type FileViewerDocumentState = {
  descriptor: FileDescriptor
  descriptorKey: string
  descriptorSignal: AbortSignal
  isClient: boolean
  isolateStyles: boolean
  resource: ViewerResource
  setControlsState: (state: ViewerControlsState | null) => void
}

function useFileViewerDocument(): FileViewerDocumentState {
  const {
    descriptor,
    descriptorKey,
    descriptorSignal,
    isClient,
    isolateStyles,
    resource,
    setControlsState,
  } = useFileViewerContext()

  return React.useMemo(
    () => ({
      descriptor,
      descriptorKey,
      descriptorSignal,
      isClient,
      isolateStyles,
      resource,
      setControlsState,
    }),
    [
      descriptor,
      descriptorKey,
      descriptorSignal,
      isClient,
      isolateStyles,
      resource,
      setControlsState,
    ]
  )
}

export function FileViewerDocument({
  bare = false,
  className,
}: FileViewerDocumentProps) {
  return (
    <InternalFileViewerDocument
      bare={bare}
      className={className}
      leafControls
      leafDownload
    />
  )
}

export function InternalFileViewerDocument({
  bare = false,
  className,
  leafControls,
  leafDownload,
}: FileViewerDocumentProps & {
  leafControls: boolean
  leafDownload: boolean
}) {
  const {
    descriptor,
    descriptorKey,
    descriptorSignal,
    isClient,
    isolateStyles,
    resource,
    setControlsState,
  } = useFileViewerDocument()
  const fallback = (
    <ViewerFallback resource={resource} className={className} bare={bare} />
  )

  React.useEffect(() => {
    setControlsState(null)
    return () => setControlsState(null)
  }, [descriptorKey, setControlsState])

  if (!isClient) return fallback

  return (
    <FileErrorBoundary
      key={descriptorKey}
      descriptor={descriptor}
      resource={resource}
      className={className}
      resetKey={descriptorKey}
    >
      <React.Suspense fallback={fallback}>
        <FileViewerRoute
          bare={bare}
          className={className}
          descriptor={descriptor}
          descriptorSignal={descriptorSignal}
          isolateStyles={isolateStyles}
          resource={resource}
          leafControls={leafControls}
          leafDownload={leafDownload}
        />
      </React.Suspense>
    </FileErrorBoundary>
  )
}

"use client"

import * as React from "react"

import { type ViewerResource } from "@/lib/viewer-resource"

import { isProseTextDescriptor, type FileDescriptor } from "./file-viewer-core"
import { CsvFileContent } from "./file-viewer-csv-viewer"
import { UnsupportedCard } from "./file-viewer-fallback"
import { HtmlFileContent } from "./file-viewer-html-viewer"

const PdfResourceContent = React.lazy(() =>
  import("@/components/ui/pdf-viewer").then((m) => ({
    default: m.PdfResourceContent,
  }))
)
const DocxResourceContent = React.lazy(() =>
  import("@/components/ui/docx-viewer").then((m) => ({
    default: m.DocxResourceContent,
  }))
)
const ImageResourceContent = React.lazy(() =>
  import("@/components/ui/image-viewer").then((m) => ({
    default: m.ImageResourceContent,
  }))
)
const PptxResourceContent = React.lazy(() =>
  import("@/components/ui/pptx-viewer").then((m) => ({
    default: m.PptxResourceContent,
  }))
)
const XlsxResourceContent = React.lazy(() =>
  import("@/components/ui/xlsx-viewer").then((m) => ({
    default: m.XlsxResourceContent,
  }))
)
const ProseTextViewer = React.lazy(() =>
  import("@/components/ui/text-viewer-chenglou").then((m) => ({
    default: m.ChenglouTextViewer,
  }))
)
const PretextMarkdownViewer = React.lazy(() =>
  import("@/components/ui/pretext-markdown-viewer").then((m) => ({
    default: m.PretextMarkdownViewer,
  }))
)
const CodeTextViewer = React.lazy(() =>
  import("@/components/ui/code-viewer").then((m) => ({
    default: m.CodeViewer,
  }))
)

export type FileViewerRouteProps = {
  bare?: boolean
  className?: string
  descriptor: FileDescriptor
  descriptorSignal: AbortSignal
  isolateStyles: boolean
  leafControls: boolean
  leafDownload: boolean
  resource: ViewerResource
}

export function FileViewerRoute({
  descriptor,
  className,
  bare = false,
  isolateStyles,
  descriptorSignal,
  resource,
  leafControls,
  leafDownload,
}: FileViewerRouteProps) {
  const { category } = descriptor
  const directLoadUrl = resource.content.directUrl ?? undefined

  if (descriptor.source.kind === "text") {
    if (category === "csv") {
      return (
        <CsvFileContent
          resource={resource}
          className={className}
          bare={bare}
          isolateStyles={isolateStyles}
        />
      )
    }
    if (category === "markdown") {
      return (
        <PretextMarkdownViewer
          source={resource.descriptor.source}
          className={className}
          download={leafDownload}
          bare={bare}
        />
      )
    }
    if (category === "html") {
      return (
        <HtmlFileContent
          resource={resource}
          className={className}
          bare={bare}
          descriptorSignal={descriptorSignal}
        />
      )
    }
    if (category === "text") {
      return renderTextViewer({
        descriptor,
        resource,
        className,
        bare,
        download: leafDownload,
      })
    }
    return (
      <UnsupportedCard
        resource={resource}
        className={className}
        bare={bare}
        showDownload={leafDownload}
      />
    )
  }

  if (!directLoadUrl) {
    if (category === "pdf" && descriptor.source.kind === "blob") {
      return (
        <PdfResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          controls={leafControls}
        />
      )
    }
    if (category === "image" && descriptor.source.kind === "blob") {
      return (
        <ImageResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          controls={leafControls}
        />
      )
    }
    if (category === "pptx" && descriptor.source.kind === "blob") {
      return (
        <PptxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          controls={leafControls}
        />
      )
    }
    if (category === "csv" && descriptor.source.kind === "blob") {
      return (
        <CsvFileContent
          resource={resource}
          className={className}
          bare={bare}
          isolateStyles={isolateStyles}
        />
      )
    }
    if (category === "html" && descriptor.source.kind === "blob") {
      return (
        <HtmlFileContent
          resource={resource}
          className={className}
          bare={bare}
          descriptorSignal={descriptorSignal}
        />
      )
    }
    if (category === "docx" && descriptor.source.kind === "blob") {
      return (
        <DocxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          controls={leafControls}
        />
      )
    }
    if (category === "xlsx" && descriptor.source.kind === "blob") {
      return (
        <XlsxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          isolateStyles={isolateStyles}
        />
      )
    }
    if (category === "markdown" && descriptor.source.kind === "blob") {
      return (
        <PretextMarkdownViewer
          source={resource.descriptor.source}
          className={className}
          download={leafDownload}
          bare={bare}
        />
      )
    }
    if (category === "text" && descriptor.source.kind === "blob") {
      return renderTextViewer({
        descriptor,
        resource,
        className,
        bare,
        download: leafDownload,
      })
    }
    return (
      <UnsupportedCard
        resource={resource}
        className={className}
        bare={bare}
        showDownload={leafDownload}
      />
    )
  }

  switch (category) {
    case "pdf":
      return (
        <PdfResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
        />
      )
    case "docx":
      return (
        <DocxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
        />
      )
    case "image":
      return (
        <ImageResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
        />
      )
    case "pptx":
      return (
        <PptxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
        />
      )
    case "xlsx":
      return (
        <XlsxResourceContent
          resource={resource}
          className={className}
          bare={bare}
          download={leafDownload}
          isolateStyles={isolateStyles}
        />
      )
    case "csv":
      return (
        <CsvFileContent
          resource={resource}
          className={className}
          bare={bare}
          isolateStyles={isolateStyles}
        />
      )
    case "markdown":
      return (
        <PretextMarkdownViewer
          source={resource.descriptor.source}
          className={className}
          download={leafDownload}
          bare={bare}
        />
      )
    case "html":
      return (
        <HtmlFileContent
          resource={resource}
          className={className}
          bare={bare}
          descriptorSignal={descriptorSignal}
        />
      )
    case "text":
      return renderTextViewer({
        descriptor,
        resource,
        className,
        bare,
        download: leafDownload,
      })
    default:
      return (
        <UnsupportedCard
          resource={resource}
          className={className}
          bare={bare}
          showDownload={leafDownload}
        />
      )
  }
}

function renderTextViewer({
  descriptor,
  resource,
  className,
  bare,
  download,
}: {
  descriptor: FileDescriptor
  resource: ViewerResource
  className?: string
  bare: boolean
  download?: boolean
}) {
  const source = resource.descriptor.source
  if (isProseTextDescriptor(descriptor)) {
    return (
      <ProseTextViewer
        source={source}
        className={className}
        download={download}
        bare={bare}
        mode="text"
      />
    )
  }
  return (
    <CodeTextViewer
      source={source}
      className={className}
      download={download}
      bare={bare}
    />
  )
}

import {
  detectCategory,
  extensionOf,
  extractName,
  resolveViewerDescriptor,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export type { FileCategory, ViewerSource }

export interface FileViewerProps {
  source: ViewerSource
  as?: FileCategory
  className?: string
  bare?: boolean
  isolateStyles?: boolean
}

export type FileDescriptor = ViewerDescriptor

export function resolveFileDescriptor({
  source,
  as,
}: FileViewerProps): FileDescriptor {
  return resolveViewerDescriptor({
    source,
    category: as,
  })
}

export function descriptorResetKey(descriptor: FileDescriptor): string {
  return [
    descriptor.identityKey,
    descriptor.displayName,
    descriptor.mimeType ?? "",
    descriptor.category,
  ].join("\u0000")
}

export function isProseTextDescriptor(descriptor: FileDescriptor): boolean {
  if (descriptor.category !== "text") return false

  const extension = extensionOf(descriptor.fileName)
  if (extension === "txt" || extension === "text") return true
  return !extension && descriptor.mimeType?.toLowerCase() === "text/plain"
}

export { detectCategory, extensionOf, extractName }

export async function timed<T>(
  label: string,
  fn: () => Promise<T>
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __FILE_VIEWER_PROFILE__?: boolean })
      .__FILE_VIEWER_PROFILE__
  if (!on) return fn()
  const t0 = performance.now()
  try {
    return await fn()
  } finally {
    console.log(
      `[file-viewer] ${label} ${(performance.now() - t0).toFixed(1)}ms`
    )
  }
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import type { ViewerResource } from "@/lib/viewer-resource"
import { Skeleton } from "@/components/ui/skeleton"
import { ViewerDownloadButton } from "@/components/ui/viewer-download"
import { ViewerErrorState } from "@/components/ui/viewer-error"

import type { FileDescriptor } from "./file-viewer-core"

const TEXT_SKELETON_FONT = 12.5
const TEXT_SKELETON_LINE_HEIGHT = 20

export function UnsupportedCard({
  resource,
  className,
  bare,
  message = "No preview for",
  showDownload = true,
}: {
  resource: ViewerResource
  className?: string
  bare?: boolean
  message?: string
  showDownload?: boolean
}) {
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-3 p-8 text-center",
        bare ? "h-full bg-muted/20" : "min-h-64 rounded-xl border bg-muted/30",
        className
      )}
      data-slot="file-viewer"
    >
      <p className="text-sm text-muted-foreground">
