export function ViewerFallback({
  resource,
  className,
  bare = false,
}: {
  resource: ViewerResource
  className?: string
  bare?: boolean
}) {
  const category = resource.descriptor.category
  const url = resource.content.directUrl

  if (
    url != null &&
    (category === "text" ||
      category === "markdown" ||
      category === "html" ||
      category === "csv")
  ) {
    return (
      <div
        data-slot="file-viewer-document-fallback"
        className={cn(
