export interface SharedAbortableRequest<T> {
  controller: AbortController
  promise: Promise<T>
  subscriberPromises: WeakMap<AbortSignal, Promise<T>>
  subscribers: Set<AbortSignal>
  settled: boolean
}

export function abortError(): DOMException {
  return new DOMException("Aborted", "AbortError")
}

export function isAbortError(error: unknown): boolean {
  return (
    (error instanceof DOMException && error.name === "AbortError") ||
    (error instanceof Error && error.name === "AbortError")
  )
}

export function promiseForSignal<T>(
  map: WeakMap<AbortSignal, Promise<T>>,
  signal: AbortSignal,
  create: () => Promise<T>
): Promise<T> {
  if (signal.aborted) return Promise.reject(abortError())

  const existingPromise = map.get(signal)
  if (existingPromise) return existingPromise

  const promise = create().catch((error: unknown) => {
    map.delete(signal)
    throw error
  })
  map.set(signal, promise)
  return promise
}

export function subscribeToAbortableRequest<T>(
  entry: SharedAbortableRequest<T>,
  signal: AbortSignal,
  onNoSubscribers: () => void
): Promise<T> {
  return promiseForSignal(entry.subscriberPromises, signal, () => {
    entry.subscribers.add(signal)

    return new Promise<T>((resolve, reject) => {
      let done = false

      const cleanup = () => {
        signal.removeEventListener("abort", onAbort)
        entry.subscribers.delete(signal)
      }

      const onAbort = () => {
        if (done) return
        done = true
        cleanup()
        if (!entry.settled && entry.subscribers.size === 0) {
          entry.controller.abort()
          onNoSubscribers()
        }
        reject(abortError())
      }

      signal.addEventListener("abort", onAbort, { once: true })

      entry.promise.then(
        (value) => {
          if (done) return
          done = true
          cleanup()
          resolve(value)
        },
        (error: unknown) => {
          if (done) return
          done = true
          cleanup()
          reject(error)
        }
      )
    })
  })
}

export const VIEWER_LRU_CACHE_MAX = 12

export function lruGet<K, V>(map: Map<K, V>, key: K): V | undefined {
  const value = map.get(key)
  if (value !== undefined) {
    map.delete(key)
    map.set(key, value)
  }
  return value
}

export function lruSet<K, V>(
  map: Map<K, V>,
  key: K,
  value: V,
  onEvict?: (key: K, value: V) => void,
  max = VIEWER_LRU_CACHE_MAX
) {
  map.delete(key)
  map.set(key, value)
  while (map.size > max) {
    const oldest = map.keys().next().value as K | undefined
    if (oldest === undefined) break
    const dropped = map.get(oldest)
    map.delete(oldest)
    if (dropped !== undefined) onEvict?.(oldest, dropped)
  }
}

import type {
  ViewerContentIdentity,
  ViewerContentText,
} from "@/lib/viewer-resource"

import { timed } from "./file-viewer-core"
import {
  abortError,
  isAbortError,
  subscribeToAbortableRequest,
  type SharedAbortableRequest,
} from "./viewer-abortable-request"
import { lruGet } from "./viewer-lru-cache"

export interface TextResourceSubscription {
  content: ViewerContentIdentity & ViewerContentText
  fileName: string
  signal: AbortSignal
}

export interface TextResourceCache {
  load(sub: TextResourceSubscription): Promise<string>
  clear(): void
  size(): number
}

export function createTextResourceCache(maxEntries = 12): TextResourceCache {
  const requests = new Map<string, SharedAbortableRequest<string>>()

  function remove(contentKey: string) {
    requests.delete(contentKey)
  }

  function pruneInactiveEntries() {
    while (requests.size > maxEntries) {
      let pruned = false
      for (const [contentKey, entry] of requests) {
        if (!entry.settled && entry.subscribers.size > 0) continue
        requests.delete(contentKey)
        if (!entry.settled) entry.controller.abort()
        pruned = true
        break
      }
      if (!pruned) break
    }
  }

  function entryFor({
    content,
    fileName,
  }: TextResourceSubscription): SharedAbortableRequest<string> {
    const contentKey = content.key
    const existingEntry = lruGet(requests, contentKey)
    if (existingEntry) return existingEntry

    const controller = new AbortController()
    let entry: SharedAbortableRequest<string> | null = null
    const promise = timed(`text:fetch ${fileName}`, () =>
      content.readText({ signal: controller.signal })
    )
      .catch((error: unknown) => {
        if (!isAbortError(error)) requests.delete(contentKey)
        throw error
      })
      .finally(() => {
        if (entry) {
          entry.settled = true
          pruneInactiveEntries()
        }
      })

    entry = {
      controller,
      promise,
      subscriberPromises: new WeakMap(),
      subscribers: new Set(),
      settled: false,
    }

    requests.set(contentKey, entry)
    return entry
  }

  return {
    load(sub) {
      if (sub.signal.aborted) return Promise.reject(abortError())

      const contentKey = sub.content.key
      const entry = entryFor(sub)
      const promise = subscribeToAbortableRequest(entry, sub.signal, () =>
        remove(contentKey)
      )
      pruneInactiveEntries()
      return promise
    },
    clear() {
      for (const entry of requests.values()) entry.controller.abort()
      requests.clear()
    },
    size() {
      return requests.size
    },
  }
}

export const textResource = createTextResourceCache()

export function loadTextResource(
  sub: TextResourceSubscription
): Promise<string> {
  return textResource.load(sub)
}

